public static int sum(int[] arr) {
    int sum = 0;
    for (int i = 0; i < arr.length; i++) {
        sum = sum + arr[i];
    }
    return sum;
}

public static double average(int[] arr) {
    return (double) sum(arr) / arr.length;
}

exercise.mainCode:
int[] arr = { 4, 8, 6, 2 };
int[] other = { 1, 2 };
System.out.println("סעיף א: " + sum(arr));
System.out.println("סעיף ב: " + average(arr) + " " + average(other));

